+      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      color: var(--text);
+      background:
+        radial-gradient(circle at top left, rgba(124, 58, 237, 0.16), transparent 32%),
+        radial-gradient(circle at top right, rgba(59, 130, 246, 0.12), transparent 28%),
+        var(--bg);
+    }
+
+    main {
+      width: min(920px, calc(100% - 32px));
+      margin: 64px auto;
+    }
+
+    .hero {
+      margin-bottom: 24px;
+      padding: 28px;
+      border: 1px solid var(--card-border);
+      border-radius: 28px;
+      background: linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.72));
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(16px);
+    }
+
+    .eyebrow {
+      display: inline-flex;
+      align-items: center;
+      gap: 8px;
+      margin-bottom: 12px;
+      padding: 8px 12px;
+      border-radius: 999px;
+      background: var(--accent-soft);
+      color: var(--accent);
+      font-size: 0.9rem;
+      font-weight: 700;
+      letter-spacing: 0.02em;
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(2rem, 4vw, 3.4rem);
+      line-height: 1.05;
+    }
+
+    .intro {
+      margin: 0;
+      max-width: 62ch;
+      color: var(--muted);
+      font-size: 1.05rem;
+      line-height: 1.7;
+    }
+
+    .faq {
+      display: grid;
+      gap: 14px;
+    }
+
+    .example {
+      overflow: hidden;
+      border: 1px solid var(--card-border);
+      border-radius: 22px;
+      background: var(--card);
+      box-shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
+      backdrop-filter: blur(12px);
+    }
+
+    .question {
+      width: 100%;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+      padding: 22px 24px;
+      border: 0;
+      background: transparent;
+      color: var(--text);
+      font: inherit;
+      text-align: left;
+      cursor: pointer;
+    }
+
+    .question span {
+      font-size: 1.08rem;
+      font-weight: 700;
+    }
+
+    .chevron {
+      flex: 0 0 auto;
+      width: 38px;
+      height: 38px;
+      display: grid;
+      place-items: center;
+      border-radius: 999px;
+      background: var(--accent-soft);
+      color: var(--accent);
+      transition: transform 180ms ease, background-color 180ms ease;
+    }
+
+    .question[aria-expanded="true"] .chevron {
+      transform: rotate(180deg);
+      background: rgba(124, 58, 237, 0.18);
+    }
+
+    .details {
+      max-height: 0;
+      overflow: hidden;
+      padding: 0 24px;
+      color: var(--muted);
+      line-height: 1.75;
+      transition: max-height 220ms ease, padding 220ms ease;
+    }
+
+    .example.open .details {
+      padding: 0 24px 22px;
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    .details strong {
+      color: var(--text);
+    }
+
+    @media (max-width: 640px) {
+      main {
+        width: min(100% - 20px, 920px);
+        margin: 20px auto 32px;
+      }
+
+      .hero {
+        padding: 22px;
+        border-radius: 22px;
+      }
+
+      .question {
+        padding: 18px 18px;
+      }
+
+      .details {
+        padding: 0 18px;
+      }
+
+      .example.open .details {
+        padding: 0 18px 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="hero" aria-labelledby="faq-title">
+      <div class="eyebrow">Cat FAQ</div>
+      <h1 id="faq-title">Everything you wanted to know about cats</h1>
+      <p class="intro">
+        A clean, expandable FAQ with quick answers on cat behavior, care, and quirks.
+        Click a question to reveal the details.
+      </p>
+    </section>
+
+    <section class="faq" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <button class="question" aria-expanded="false">
+          <span>Why do cats purr?</span>
+          <span class="chevron">⌄</span>
+        </button>
+        <div class="details" hidden>
+          <p>
+            Cats purr for comfort, communication, and sometimes self-soothing. It often means
+            they feel relaxed, but purring can also happen when they are stressed or recovering.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" aria-expanded="false">
+          <span>How much sleep do cats need?</span>
+          <span class="chevron">⌄</span>
+        </button>
+        <div class="details" hidden>
+          <p>
+            Most cats sleep around 12 to 16 hours a day, and some kittens or senior cats sleep
+            even more. Their bursty hunting instincts make short naps a normal part of the day.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" aria-expanded="false">
+          <span>Why do cats knead with their paws?</span>
+          <span class="chevron">⌄</span>
+        </button>
+        <div class="details" hidden>
+          <p>
+            Kneading is a comforting behavior that starts in kittenhood. Adult cats often do it
+            when they are content, marking a favorite person or blanket with scent glands in their paws.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" aria-expanded="false">
+          <span>Should I feed my cat wet or dry food?</span>
+          <span class="chevron">⌄</span>
+        </button>
+        <div class="details" hidden>
+          <p>
+            Many cats do well with a mix of both. Wet food helps with hydration, while dry food can be
+            convenient. The best choice depends on your cat's age, health, and preferences.
+          </p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    const examples = document.querySelectorAll(".example");
+
+    examples.forEach((example) => {
+      const button = example.querySelector(".question");
+      const details = example.querySelector(".details");
+
+      button.addEventListener("click", () => {
+        const isOpen = example.classList.toggle("open");
+        button.setAttribute("aria-expanded", String(isOpen));
+        details.hidden = !isOpen;
+
+        if (isOpen) {
+          details.style.maxHeight = `${details.scrollHeight}px`;
+        } else {
+          details.style.maxHeight = "0px";
+        }
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
